  "bq_location": "EU",
  "config_sheet_id": "YOUR_GOOGLE_SHEET_ID",
  "gads_api_version": "v21",
  "gads_login_customer_id": "1234567890",
  "gads_developer_token": "YOUR_GOOGLE_ADS_DEVELOPER_TOKEN",
  "meta_api_version": "v23.0",
  "meta_purchase_action_types": [
    "omni_purchase",
    "purchase",
    "offsite_conversion.fb_pixel_purchase"
  ],
  "lookback_days": 7,
  "search_terms_lookback_days": 30,
  "anthropic_model": "claude-opus-5",
  "anthropic_effort": "medium",
  "max_new_tasks_per_run": 10,
  "alert_email_from": "n8n@your-agency.sk",
  "alert_email_to": "ppc@your-agency.sk",
  "workflow_ids": {
    "wf3_analyst": "REPLACE_AFTER_IMPORT",
    "wf4_asana": "REPLACE_AFTER_IMPORT",
    "error": "REPLACE_AFTER_IMPORT"
  },
  "rule_defaults": {
    "pacing_tolerance": 0.15,
    "pacing_min_days": 5,
    "kpi_tolerance": 0.15,
    "wow_drop": 0.25,
    "wow_min_conv": 5,
    "min_spend_7d_eur": 100,
    "min_spend_campaign_7d_eur": 50,
    "max_frequency": 3.0,
    "outage_min_daily_conv": 3,
    "outage_drop": 0.7,
    "scale_lost_is_budget": 0.2,
    "scale_min_conv": 3,
    "search_term_min_cost_eur": 15
  },
  "asana": {
    "workspace_gid": "REPLACE",
    "project_gid": "REPLACE",
    "section_new_gid": "REPLACE",
    "default_assignee_gid": "",
    "due_days": {
      "P1": 1,
      "P2": 3,
      "P3": 7
    },
    "fields": {
      "country": {
        "gid": "REPLACE",
        "options": {
          "SK": "",
          "CZ": "",
          "HU": "",
          "PL": "",
          "RO": "",
          "BG": "",
          "HR": "",
          "SI": "",
          "GR": "",
          "ALL": ""
        }
      },
      "platform": {
        "gid": "REPLACE",
        "options": {
          "GOOGLE_ADS": "",
          "META": "",
          "BOTH": ""
        }
      },
      "type": {
        "gid": "REPLACE",
        "options": {
          "TRACKING": "",
          "BUDGET": "",
          "PERFORMANCE": "",
          "WASTE": "",
          "SCALE": "",
          "CREATIVE": "",
          "SEARCH_TERMS": "",
          "POLICY": "",
          "LEARNING": "",
          "DATA_QUALITY": ""
        }
      },
      "priority": {
        "gid": "REPLACE",
        "options": {
          "P1": "",
          "P2": "",
          "P3": ""
        }
      },
      "alert_id": {
        "gid": "REPLACE"
      },
      "impact": {
        "gid": "REPLACE"
      }
    }
  },
  "gaql": {
    "campaigns": "SELECT\n  segments.date,\n  customer.id,\n  customer.descriptive_name,\n  customer.currency_code,\n  campaign.id,\n  campaign.name,\n  campaign.status,\n  campaign.advertising_channel_type,\n  campaign.bidding_strategy_type,\n  campaign.primary_status,\n  campaign.primary_status_reasons,\n  campaign_budget.amount_micros,\n  metrics.cost_micros,\n  metrics.impressions,\n  metrics.clicks,\n  metrics.conversions,\n  metrics.conversions_value,\n  metrics.search_impression_share,\n  metrics.search_budget_lost_impression_share,\n  metrics.search_rank_lost_impression_share\nFROM campaign\nWHERE segments.date BETWEEN '{since}' AND '{until}'\n  AND campaign.status != 'REMOVED'\n",
    "search_terms": "SELECT\n  customer.id,\n  customer.currency_code,\n  campaign.id,\n  campaign.name,\n  ad_group.id,\n  ad_group.name,\n  search_term_view.search_term,\n  metrics.cost_micros,\n  metrics.clicks,\n  metrics.conversions,\n  metrics.conversions_value\nFROM search_term_view\nWHERE segments.date BETWEEN '{st_since}' AND '{until}'\n  AND metrics.cost_micros > 0\nORDER BY metrics.cost_micros DESC\nLIMIT 2000\n",
    "disapproved": "SELECT\n  customer.id,\n  campaign.id,\n  campaign.name,\n  ad_group.id,\n  ad_group.name,\n  ad_group_ad.ad.id,\n  ad_group_ad.ad.name,\n  ad_group_ad.policy_summary.approval_status\nFROM ad_group_ad\nWHERE ad_group_ad.status = 'ENABLED'\n  AND campaign.status = 'ENABLED'\n  AND ad_group.status = 'ENABLED'\n  AND ad_group_ad.policy_summary.approval_status = 'DISAPPROVED'\n"
  }
};

// $today = start of today in the workflow timezone (Europe/Bratislava).
const until = $today.minus({ days: 1 }).toISODate();
const since = $today.minus({ days: S.lookback_days }).toISODate();
const stSince = $today.minus({ days: S.search_terms_lookback_days }).toISODate();
// Pull a few extra days of FX so weekends/holidays resolve to the last ECB fixing.
const fxFrom = $today.minus({ days: Math.max(S.lookback_days, S.search_terms_lookback_days) + 7 }).toISODate();

const fill = (q) => q.replaceAll('{since}', since).replaceAll('{until}', until).replaceAll('{st_since}', stSince);

return [{
  json: {
    ...S,
    since,
    until,
    st_since: stSince,
    fx_from: fxFrom,
    gaql_campaigns: fill(S.gaql.campaigns),
    gaql_search_terms: fill(S.gaql.search_terms),
    gaql_disapproved: fill(S.gaql.disapproved),
    meta_time_range: JSON.stringify({ since, until }),
  },
}];

